"""Dependency-free static site generator. All factual records live in data/trip.json."""
import json, html, csv, io
from pathlib import Path
from datetime import date, timedelta
D=json.loads(Path('data/trip.json').read_text())
S={s['id']:s for s in D['sources']}
R={r['id']:r for r in D['restaurants']}
H={h['id']:h for h in D['hotels']}
def e(x):return html.escape(str(x),quote=True)
def link(url,label,cls=''):
    ext=url.startswith('http')
    return f'<a class="{cls}" href="{e(url)}"'+(' target="_blank" rel="noopener noreferrer"' if ext else '')+f'>{e(label)}'+(' <span aria-hidden="true">↗</span>' if ext else '')+'</a>'
def refs(ids):return '<div class="refs">'+''.join(link(S[i]['url'],S[i]['title']) for i in ids)+'</div>'
def empty(reason='Not verified'):
    return f'<span class="missing" aria-label="{e(reason)}"><span class="blank-value" aria-hidden="true"></span><small>{e(reason)}</small></span>'
def val(x,reason='Not verified'):return e(x) if x is not None else empty(reason)
def tag(text,tone='neutral'):return f'<span class="badge {tone}">{e(text)}</span>'
def money(x):return 'CNY '+f'{x:,.2f}'.removesuffix('.00')
def table(headers,rows,id='',caption=''):
    return '<div class="table-wrap"><table'+(f' id="{id}"' if id else '')+'>'+(f'<caption>{caption}</caption>' if caption else '')+'<thead><tr>'+''.join(f'<th scope="col">{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr'+(' '+attrs if attrs else '')+'>'+''.join(f'<td data-label="{e(html.unescape(__import__("re").sub("<[^>]+>","",headers[i])))}">{v}</td>' for i,v in enumerate(cells))+'</tr>' for cells,attrs in rows)+'</tbody></table></div>'
def panel(title,body,cls=''):return f'<section class="panel {cls}"><h2>{title}</h2>{body}</section>'
def note(title,body):return f'<div class="notice"><span class="notice-icon" aria-hidden="true">i</span><div><strong>{title}</strong><p>{body}</p></div></div>'
def toolbar(target,placeholder,options=None):
    return f'<div class="toolbar"><label class="search"><span aria-hidden="true">⌕</span><input type="search" data-search="{target}" placeholder="{e(placeholder)}" aria-label="{e(placeholder)}"></label>'+(''.join(f'<button class="filter {"active" if i==0 else ""}" data-filter="{e(v)}" data-target="{target}" aria-pressed="{str(i==0).lower()}">{e(t)}</button>' for i,(v,t) in enumerate(options)) if options else '')+f'<span class="result-count" id="{target}-count" aria-live="polite"></span></div>'
def media(ids):
    if not ids:return empty('No matching social link verified')
    return ''.join(f'<div class="media-link">{link(S[i]["url"], S[i]["title"])}<small>{e(S[i]["note"])}</small></div>' for i in ids)
